def roman_to_int(s):
    roman_dict = {'M': 1000, 'D': 500, 'C': 100, 'L': 50, 'X': 10, 'V': 5, 'I': 1}
    s = s.upper()
    if len(s) == 0 or not s.isalpha():
        return None
    i = 0
    total = 0
    while i < len(s):
        if i + 1 < len(s) and roman_dict[s[i]] < roman_dict[s[i + 1]]:
            total += roman_dict[s[i + 1]] - roman_dict[s[i]]
            i += 2
        else:
            total += roman_dict[s[i]]
            i += 1
    return total
```

