    num = int(''.join(filter(str.isdigit, s)))
    total = 0
    for i in range(len(num)):
        digit = num % 10
        if i % 2 == 0:
            digit = digit * 2
        if digit > 9:
            digit -= 9
        total += digit
    return total % 10 == 0
